import { useCallback, useMemo, useState } from "react";
import { ThreeStage } from "@/components/ThreeStage";
import { BottomBar } from "@/components/jig/BottomBar";
import { RightJig } from "@/components/jig/RightJig";
import { useJigState } from "@/components/jig/useJigState";
import { RIG_SECTIONS } from "@/three/rig/rigSchema";
import { APP_TITLE, activeScene } from "@/data/jigData";

/**
 * 3D UI jig shell (generated by 3d-ui-jig). Full-viewport WebGL stage +
 * schema-driven right-hand jig + bottom dock. `?nojig=1` = clean capture.
 * Swap scenes in src/data/jigData.ts.
 */
export function App() {
  const jig = useJigState(activeScene);
  const [sceneState, setSceneState] = useState<Record<string, unknown>>({});
  const [extraOpenRequest, setExtraOpenRequest] = useState(0);

  const sections = useMemo(() => [...activeScene.schema, ...RIG_SECTIONS], []);
  const onSceneEvent = useCallback((key: string, value: unknown) => {
    setSceneState((prev) => (prev[key] === value ? prev : { ...prev, [key]: value }));
  }, []);

  const Extra = activeScene.ExtraSection;
  const focused = sceneState.focusedIndex !== undefined && sceneState.focusedIndex !== null;

  return (
    <div
      className="relative h-screen w-screen overflow-hidden select-none"
      style={{ backgroundColor: jig.values.rig.backdrop.color }}
    >
      <main className="h-full w-full">
        <ThreeStage
          module={activeScene}
          values={jig.values}
          resetSignal={jig.resetSignal}
          onSceneEvent={onSceneEvent}
        />
      </main>

      {!jig.noJig && (
        <>
          <RightJig
            title={APP_TITLE}
            sections={sections}
            values={jig.values}
            onChange={jig.setValue}
            presetNames={jig.presetNames}
            activePreset={jig.presetName}
            onPresetSelect={jig.applyPreset}
            onReset={jig.reset}
            expandRequest={extraOpenRequest}
            extra={
              Extra ? (
                <Extra
                  values={jig.values}
                  setScene={jig.setScene}
                  sceneState={sceneState}
                  openRequest={extraOpenRequest}
                />
              ) : null
            }
          />
          <BottomBar
            module={activeScene}
            sections={sections}
            values={jig.values}
            onChange={jig.setValue}
            presetName={jig.presetName}
            onCyclePreset={jig.cyclePreset}
            onResetView={jig.resetView}
            onEditExtra={Extra ? () => setExtraOpenRequest((n) => n + 1) : undefined}
            resetLabel={focused ? "Exit Focus" : undefined}
          />
        </>
      )}
    </div>
  );
}

export default App;
